시간 ~ 끝에 해당하는 값을 1씩 올려준 뒤 최대값을 찾고 이 값이 맨 처음 나온 위치와 처음으로 끝난 위치를 출력하는 문제.
하지만 시간이 21억까지 이기 때문에 hash map을 이용한 좌표 압축을 해줘야 함.
또한 좌표 압축을 해도 입력이 최대 100만개에 2개씩 들어오기 때문에 200만개가 나올 수 있어서 각 위치에 대한 값 갱신을 하나하나 해주면 시간 초과가 발생함. 
이에 따라서 누적합을 이용해서 구현해줘야 하는데 시작 시간에 해당하는 sum값을 1 올려주고 끝나는 시간에 해당하는 sum값을 1 내려주는 걸 반복한 뒤에 처음부터 sum 끼리 누적합을 구해주면 O(n) 시간에 이를 해결할 수 있음.
해당 과정에서 가장 큰 수를 저장해놓고 있다가 다시 한번 순회하면서 해당 값이 나온 처음 위치와 이게 끝난 위치를 출력하면 됨.

```cpp
#include <bits/stdc++.h>
using namespace std;

int n;
vector<pair<int,int>> v;
vector<int> for_sort;
unordered_map<int, int> um, reverse_um;

void input(){
    cin >> n;
    v.resize(n);
    for(int i=0;i<n;i++){
        int a,b; cin >> a >> b;
        v[i] = {a,b};
        for_sort.push_back(a);
        for_sort.push_back(b);
    }
    sort(for_sort.begin(), for_sort.end());
    for(int i=0;i<2*n;i++){
        um[for_sort[i]] = i;
        reverse_um[i] = for_sort[i];
    }
}

void solve(){
    vector<int> sum(2*n, 0);
    for(int i=0;i<n;i++){
        auto p = v[i];
        int s = um[p.first], e = um[p.second];
        sum[s]++, sum[e]--;
    }
    int mx = sum[0];
    for(int i=1;i<2*n;i++){
        sum[i] += sum[i-1];
        mx = max(mx, sum[i]);
    }
    cout << mx << '\n';

    bool flag = false;
    pair<int,int> ans;
    for(int i=0;i<2*n;i++){
        if(sum[i] == mx && !flag){
            flag = true;
            ans.first = reverse_um[i];
        }
        if(sum[i] != mx && flag){
            ans.second = reverse_um[i];
            break;
        }
    }
    cout << ans.first << " " << ans.second;
}

int main(){
    cin.tie(0)->sync_with_stdio(0);
    freopen("input.txt", "r", stdin);
    
    input();
    solve();

    return 0;
}
```

`SES_UNCAUGHT_EXCEPTION: SyntaxError: redeclaration of const api` occurs when `public/app.js` is evaluated more than once in a constrained runtime (SES), because `api` is declared at top-level lexical scope.  
This change removes top-level redeclaration risk while preserving the existing `window.museumApp` contract used by all pages.

- **Scope isolation**
  - Wrapped `public/app.js` in an IIFE so `api` and helper bindings are function-scoped per evaluation instead of top-level lexical globals.

- **Public API stability**
  - Kept `window.museumApp = { api, getParam, byId, ratingText, renderComments }` unchanged so existing page scripts (`museum.html`, `artifact.html`, `museums.html`, `auth.html`) continue to consume the same interface.

- **Resulting behavior**
  - Re-evaluating the script no longer throws `redeclaration of const api`; each load creates a fresh local scope and reassigns `window.museumApp`.

```js
(() => {
  const api = { /* get/post */ };
  function getParam(name) { /* ... */ }
  function byId(id) { /* ... */ }

  window.museumApp = { api, getParam, byId, ratingText, renderComments };
})();
```
